---@field MyRanking                     	UnityEngine.RectTransform               
---@field LoopView                      	SuperScrollView.LoopListView2           
local LadderCompetionRankDialog = Class('LadderCompetionRankDialog')


function LadderCompetionRankDialog:__init()
    ---@type LadderRankPlayerDojo[]
    self.rankDojoList_ = {}
    ---@type LadderRankPlayerDojo
    self.myRankDojo_   = LadderRankPlayerDojo.New()
end


function LadderCompetionRankDialog:__delete()
    self.rankDojoList_ = nil
    self.myRankDojo_   = nil
