function LadderCompetionRankDialog:Awake()
    SetListViewAction(self.LoopView, Bind(self, self.OnUpdateRankListCellHandler_), RankCellNodeName)
end


function LadderCompetionRankDialog:OnInitialize()
    return CoWaitDo(function()
        --local initParams   = self.controller.Argument.parameters or {}
        --self.activityUuid_ = initParams.activityUuid
        self:RequestRankData_()
    end)
end


function LadderCompetionRankDialog:OnFinalize()
