-------------------------------------------------
-- private

function LadderCompetionRankDialog:RequestRankData_()
    -- request rankData
    local success = false
    GameUtils.Request(Interfaces.LADDER_RANK, {}, function(request, response)
        success = true
        if checkInt(response.errCode) == 0 then
            local allRankData = checkTable(response.data)
            
            -- other rankData
            self.rankDojoList_ = {}
            for rankIndex, rankData in ipairs(allRankData.rank or {}) do
                local rankPlayerDojo = LadderRankPlayerDojo.New()
                rankPlayerDojo:Fill(rankData)
                rankPlayerDojo.ranking = rankIndex
                self.rankDojoList_[rankIndex] = rankPlayerDojo
            end

            -- myself rankData
            local playerDojo = playerComponent.playerDojo
            self.myRankDojo_:Fill(allRankData.myRank)
            self.myRankDojo_.playerId    = playerDojo.playerId
            self.myRankDojo_.name        = playerDojo.playerName
            self.myRankDojo_.level       = playerDojo.level
            self.myRankDojo_.avatar      = playerDojo.playerAvatar
            self.myRankDojo_.avatarFrame = playerDojo.playerAvatarFrame

            -- init views
            self:RefreshView_()
        end
    end)

    while not success do
        coroutine.yield()
    end
end


function LadderCompetionRankDialog:RefreshView_()
    local hasRankData = #self.rankDojoList_ > 0
    CfUtils.SetActive(self.EmptyNode, not hasRankData)
    CfUtils.SetActive(self.LayoutListAndMyselef, hasRankData)

    if hasRankData then
        self:RefreshRankList_()
        self:RefreshMyRank_()
    end
end


function LadderCompetionRankDialog:RefreshRankList_()
    GameUtils.ReloadData(self.LoopView, #self.rankDojoList_)
end


function LadderCompetionRankDialog:RefreshMyRank_()
    CfUtils.SetActive(self.MyRanking, true)
    ---@type LadderCompetionRankCellNode
    local cellEnv = CfUtils.GetLuaScr(self.MyRanking.gameObject, RankCellNodePath)
    if cellEnv then
        -- init cell
        cellEnv:SetMyRank(true)
        cellEnv:SetCellData(self.myRankDojo_)
    end
end


-------------------------------------------------
-- handler

---@param listView SuperScrollView.LoopListView2
---@param luaIndex integer
---@return SuperScrollView.LoopListViewItem2
function LadderCompetionRankDialog:OnUpdateRankListCellHandler_(listView, luaIndex)
    local cellNode = listView:NewListViewItem(RankCellNodeName)
    local cellData = checkTable(self.rankDojoList_[luaIndex])
    ---@type LadderCompetionRankCellNode
    local cellEnv = CfUtils.GetLuaScr(cellNode, RankCellNodePath)
    if cellEnv then
        -- init cell
        cellEnv:SetLuaIndex(luaIndex)
        cellEnv:SetCellData(cellData)
        
        if listView.DisplayItemNumber < listView.DisplayItemCount then
            cellEnv:PlayDelayAnimByShow(listView.DisplayItemNumber)
            listView.DisplayItemNumber = listView.DisplayItemNumber + 1
        else
            cellEnv:PlayAnimByIdle()
        end
    end
    return cellNode
end


return LadderCompetionRankDialog
